#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn every_generated_kind_has_sql() {
        for kind in GENERATED_KINDS {
            assert!(generated_supported(kind));
            let sql = generated_sql(kind).unwrap_or_else(|| panic!("missing {kind}"));
            assert!(sql.contains('?') || sql.contains("$1"));
        }
    }
}
